fn distinct_buses(items: &CollectedVec<usize>) -> usize {
    let mut buses = items.to_vec();
    buses.sort_unstable();
    buses.dedup();
    buses.len()
}

/// One hard point per bus over the workshop limit that day.
fn collected_values_weight(_day: &usize, items: &CollectedVec<usize>) -> HardSoftScore {
    let excess = distinct_buses(items).saturating_sub(MAX_BUSES_IN_WORKSHOP);
    HardSoftScore::of_hard(excess as i64)
}

pub fn constraint() -> impl IncrementalConstraint<Schedule, HardSoftScore> {
    ConstraintFactory::<Schedule, HardSoftScore>::new()
        .for_each(Schedule::jobs())
        .join((
            Schedule::technicians(),
            equal_bi(entity_join_key, fact_join_key),
        ))
        .penalize(hard_weight(join_weight))
        .named("technician_skill")
}

fn balance_weight(_scope: &usize, load: &LoadBalance<Option<usize>>) -> HardSoftScore {
    HardSoftScore::of_soft(load.loads().values().map(|jobs| jobs * jobs).sum())
}

fn unary_condition(entity: &Job) -> bool {
    entity.day.is_some_and(|day| day as i64 > entity.due_day)
}

let breakdown = ClosureProblemChange::<Schedule, _>::new("bus breakdown", move |director| {
    let jobs = &mut director.working_solution_mut().jobs;
    let job_id = format!("job-{:02}", jobs.len() + 1);
    jobs.push(Job::new(
        job_id,
        request.bus_idx,
        request.skill,
        request.earliest_day,
        request.due_day,
    ));
});
